param(); $jsonPath="tests/fixtures/lhm_data.json"; $data=Get-Content $jsonPath -Raw | ConvertFrom-Json; $cpu=($data.sensors | Where-Object { $_.path -like "/intelcpu/*/temperature/*" -and $_.name -notmatch "Distance|TjMax|Limit" }); $principal=$cpu | Where-Object { $_.name -eq "CPU Package" } | Select-Object -First 1; if (-not $principal) { $principal=$cpu | Where-Object { $_.name -match "Core (Tctl/Tdie)|Tdie|Tctl|Core Max" } | Select-Object -First 1 }; $rest=$cpu | Where-Object { $_.name -notin @("CPU Package","Core (Tctl/Tdie)","Tdie","Tctl","Core Max","Core Average","CPU Core #1","CPU Core #2") }; Write-Output (@{"cpu_package"=$principal.name;"cpu_package_c"=$principal.value;"detalle"=$rest | Select-Object name,value | ConvertTo-Json -Compress;"motivo"="Datos reales del fixture; no inventados"})